pub(crate) fn has_directory_write_search_access(
    meta: &vfs::Metadata,
    uid: u32,
    gid: u32,
    groups: &[u32],
) -> bool {
    if uid == 0 {
        return true;
    }
    (permission_class_bits(meta, uid, gid, groups) & 0o3) == 0o3
}

pub(crate) fn apply_created_inode_metadata(
    parent_meta: &vfs::Metadata,
    inode: &Arc<dyn vfs::IndexNode>,
    mode: vfs::InodeMode,
    uid: u32,
    gid: u32,
) -> Result<(), isize> {
    let mut meta = inode.metadata().map_err(|e| -(e as isize))?;
    let parent_setgid = parent_meta.mode.contains(vfs::InodeMode::S_ISGID);
    let child_gid = if parent_setgid { parent_meta.gid } else { gid };

    meta.uid = uid;
    meta.gid = child_gid;
    meta.mode = vfs::InodeMode::from(meta.file_type) | (mode & vfs::InodeMode::S_IALLUGO);
    if meta.mode.contains(vfs::InodeMode::S_ISGID) && uid != 0 && gid != child_gid {
        meta.mode.remove(vfs::InodeMode::S_ISGID);
    }

    match inode.set_metadata(&meta) {
        Ok(()) | Err(SyscallErr::ENOSYS) => Ok(()),
        Err(e) => Err(-(e as isize)),
    }
}

pub(crate) fn apply_current_umask(mode: vfs::InodeMode) -> vfs::InodeMode {
    let task = current_task().unwrap();
    let fs_ref = task.process.fs();
    let mask = fs_ref.lock().umask & 0o777;
    // Only apply umask to permission bits (S_IALLUGO).
    // Callers that need S_IFMT type bits (mknodat) must re-pack them
    // from the extracted FileType after calling this function.
    let perm_bits = mode & vfs::InodeMode::S_IALLUGO;
    perm_bits & !vfs::InodeMode::from_bits_truncate(mask)
}

pub(crate) fn metadata_to_stat(meta: &vfs::Metadata) -> Stat {
    Stat {
        st_dev: meta.dev_id as u64,
        st_ino: meta.inode_id as u64,
        st_mode: meta.mode.bits() | vfs::InodeMode::from(meta.file_type).bits(),
        st_nlink: meta.nlinks as u32,
        st_uid: meta.uid,
        st_gid: meta.gid,
        st_rdev: meta.raw_dev as u64,
        __pad: 0,
        st_size: meta.size,
        st_blksize: meta.blk_size as u32,
        __pad2: 0,
        st_blocks: meta.blocks as u64,
        st_atime: meta.atime,
        st_mtime: meta.mtime,
        st_ctime: meta.ctime,
        __unused: 0,
    }
}

pub(crate) fn metadata_to_statx(meta: &vfs::Metadata, _mask: u32) -> Statx {
    let stat = metadata_to_stat(meta);
    // Linux 6.6: stx_mask reports STATX_BASIC_STATS — the fields this
    // implementation always fills, regardless of what was requested.
    let actual_mask = STATX_BASIC_STATS;
    let mut statx = Statx::new(
        actual_mask,
        stat.get_nlink(),
        stat.get_mode() as u16,
        stat.get_ino() as u64,
        stat.get_size() as u64,
        stat.get_atime() as i64,
        stat.get_ctime() as i64,
        stat.get_mtime() as i64,
        ((stat.get_rdev() & 0xffff_00) >> 8) as u32,
        (stat.get_rdev() & 0xff) as u32,
        ((stat.get_dev() & 0xffff_00) >> 8) as u32,
        (stat.get_dev() & 0xff) as u32,
    );
    statx.stx_uid = stat.st_uid;
    statx.stx_gid = stat.st_gid;
    // Use metadata-backed block size (filesystem preferred I/O size).
    statx.stx_blksize = meta.blk_size as u32;
    // Use metadata-backed block count in 512-byte units.
    statx.stx_blocks = meta.blocks as u64;
    statx
}

pub(crate) fn open_file_at(
    dirfd: usize,
    path: &str,
    flags: OpenFlags,
    mode: vfs::InodeMode,
) -> Result<Arc<vfs::File>, isize> {
    let start = if path.starts_with('/') {
        crate::fs::current_root_inode()
    } else {
        resolve_start_inode(dirfd)?
    };
    if path.is_empty() {
        let md = start.metadata().map_err(|e| -(e as isize))?;
        return Ok(vfs::File::new_without_open(
            start,
            _open_flags_to_vfs_flags(flags),
            md.file_type,
        ));
    }

    // Paths like ".", "./", ".//" resolve to the start inode itself
    if path == "." || path.trim_end_matches('/') == "." {
        // O_TMPFILE is not supported. apk uses openat(cache_fd, ".", O_TMPFILE|...)
        // to create unnamed temp files. If we open the directory as writable,
        // the subsequent write() returns EISDIR and apk sees "Is a directory".
        // Return EOPNOTSUPP so userspace falls back to named temp files.
        if flags.contains(OpenFlags::O_TMPFILE) {
            return Err(crate::syscall::errno::EOPNOTSUPP);
        }
        let md = start.metadata().map_err(|e| -(e as isize))?;
        if flags.contains(OpenFlags::O_CREAT | OpenFlags::O_EXCL) {
            return Err(EEXIST);
        }
        if flags.contains(OpenFlags::O_PATH) {
            return Ok(vfs::File::new_without_open(
                start,
                vfs::FileFlags::from_bits_truncate(
                    vfs::FileFlags::O_DIRECTORY.bits()
                        | vfs::FileFlags::O_NOFOLLOW.bits()
                        | vfs::FileFlags::O_PATH.bits()
                        | vfs::FileFlags::O_CLOEXEC.bits(),
                ) & _open_flags_to_vfs_flags(flags),
                md.file_type,
            ));
        }
        if flags.contains(OpenFlags::O_DIRECTORY) && md.file_type != FileType::Dir {
            return Err(ENOTDIR);
        }
        return vfs::File::new_with_metadata(start, _open_flags_to_vfs_flags(flags), md)
            .map_err(|e| -(e as isize));
    }

    let (uid, fsgid, groups) = caller_ids_and_groups();
    // uid==0 (root) bypasses DAC — skip the redundant path walk
    if uid != 0 {
        let parent_result = check_parent_search_access(&start, path, uid, fsgid, &groups);
        if parent_result != SUCCESS {
            return Err(parent_result);
        }
    }

    let follow_final = !flags.contains(OpenFlags::O_NOFOLLOW);
    match vfs_lookup(&start, path, follow_final) {
        Ok(target) => {
            // O_PATH + O_NOFOLLOW opens the symlink itself, not ELOOP (Linux semantics)
            if !follow_final && !flags.contains(OpenFlags::O_PATH) {
                if let Ok(md) = target.metadata() {
                    if md.file_type == FileType::SymLink {
                        return Err(ELOOP);
                    }
                }
            }
            if flags.contains(OpenFlags::O_CREAT | OpenFlags::O_EXCL) {
                return Err(EEXIST);
            }
            let md = target.metadata().map_err(|e| -(e as isize))?;

            // O_DIRECTORY must fail ENOTDIR before any special-case handling.
            // Previously this check was after the FIFO branch, making it unreachable
            // for named FIFOs — open(fifo, O_DIRECTORY) would succeed instead of ENOTDIR.
            if flags.contains(OpenFlags::O_DIRECTORY) && md.file_type != FileType::Dir {
                return Err(ENOTDIR);
            }

            // O_PATH: skip all permission checks and side effects — just build a path-only fd.
            // Linux v6.6: O_PATH masks flags to O_DIRECTORY|O_NOFOLLOW|O_PATH|O_CLOEXEC,
            // dispatches to do_o_path() bypassing may_open() entirely.
            if flags.contains(OpenFlags::O_PATH) {
                return Ok(vfs::File::new_without_open(
                    target,
                    vfs::FileFlags::from_bits_truncate(
                        vfs::FileFlags::O_DIRECTORY.bits()
                            | vfs::FileFlags::O_NOFOLLOW.bits()
                            | vfs::FileFlags::O_PATH.bits()
                            | vfs::FileFlags::O_CLOEXEC.bits(),
                    ) & _open_flags_to_vfs_flags(flags),
                    md.file_type,
                ));
            }

            // Read permission check (Linux: O_RDONLY→MAY_READ, O_RDWR→MAY_READ|MAY_WRITE)
            // Applies to ALL file types (regular, FIFO, device, socket) — not just regular files.
            // O_RDONLY is the default (flags & 3 == 0) — must still check MAY_READ.
            // Skip for O_PATH (already returned early above).
            let access_mode = flags.bits() & 0o3;
            if access_mode == 0 || access_mode == 2 {
                // O_RDONLY (0) or O_RDWR (2) — both need MAY_READ
                if !has_final_access(&md, FaccessatMode::R_OK, uid, fsgid, &groups) {
                    return Err(EACCES);
                }
            }

            // O_NOATIME: check that caller is owner, group member, or root
            if flags.contains(OpenFlags::O_NOATIME) {
                let (uid, _gid) = open_subject_ids();
                if uid != 0 && uid != md.uid {
                    return Err(EPERM);
                }
            }
            // Named FIFO: substitute the filesystem inode with a Pipe-backed inode
            if md.file_type == FileType::Pipe {
                const O_ACCMODE: u32 = 0o3;
                let access = flags.bits() & O_ACCMODE;
                let for_read = access != OpenFlags::O_WRONLY.bits();
                let for_write =
                    access == OpenFlags::O_WRONLY.bits() || access == OpenFlags::O_RDWR.bits();
                return match crate::fs::dev::pipe::fifo_open(
                    (md.dev_id, md.inode_id),
                    for_read,
                    for_write,
                    flags.contains(OpenFlags::O_NONBLOCK),
                ) {
                    Ok(pipe_inode) => Ok(vfs::File::new_without_open(
                        pipe_inode,
                        _open_flags_to_vfs_flags(flags),
                        vfs::FileType::Pipe,
                    )),
                    Err(e) => Err(-(e as isize)),
                };
            }
            if md.file_type == FileType::Dir
                && (flags.contains(OpenFlags::O_WRONLY)
                    || flags.contains(OpenFlags::O_RDWR)
                    || flags.contains(OpenFlags::O_CREAT))
            {
                // Linux 6.6+: O_CREAT|O_DIRECTORY is EINVAL, not EISDIR
                if flags.contains(OpenFlags::O_CREAT) && flags.contains(OpenFlags::O_DIRECTORY) {
                    return Err(EINVAL);
                }
                return Err(EISDIR);
            }
            if open_requests_write(flags) {
                if is_executable_inode_busy(&target) {
                    return Err(ETXTBSY);
                }
                if !has_final_access(&md, FaccessatMode::W_OK, uid, fsgid, &groups) {
                    return Err(EACCES);
                }
            }
            if flags.contains(OpenFlags::O_TRUNC) {
                target.resize(0).map_err(|e| -(e as isize))?;
            }
            vfs::File::new_with_metadata(target, _open_flags_to_vfs_flags(flags), md)
                .map_err(|e| -(e as isize))
        }
        Err(errno) if errno == ENOENT => {
            if !flags.contains(OpenFlags::O_CREAT) || flags.contains(OpenFlags::O_DIRECTORY) {
                return Err(errno);
            }
            let (parent, leaf) = vfs_lookup_parent_for_start(&start, path)?;
            let parent_meta = parent.metadata().map_err(|e| -(e as isize))?;
            check_parent_write_search_access(&parent, uid, fsgid, &groups)?;
            let create_mode = apply_current_umask(mode);

            let setgid = parent_meta.mode.contains(vfs::InodeMode::S_ISGID);
            let child_gid = if setgid { parent_meta.gid } else { fsgid };

            let mut effective_mode = create_mode;
            if effective_mode.contains(vfs::InodeMode::S_ISGID) && uid != 0 && fsgid != child_gid {
                effective_mode.remove(vfs::InodeMode::S_ISGID);
            }

            let inode = parent
                .create_with_attrs(
                    &leaf,
                    FileType::File,
                    vfs::CreateAttrs {
                        mode: effective_mode,
                        uid,
                        gid: child_gid,
                    },
                )
                .map_err(|e| -(e as isize))?;
            vfs::File::new(inode, _open_flags_to_vfs_flags(flags)).map_err(|e| -(e as isize))
        }
        Err(errno) => Err(errno),
    }
}

pub(crate) fn check_memfd_truncate_seals(file: &vfs::File, new_len: usize) -> Result<(), isize> {
    if let Some(seals) = file.memfd_seal_bits() {
        let current_len = file.metadata().map_err(|e| -(e as isize))?.size.max(0) as usize;
        if new_len < current_len && (seals & vfs::F_SEAL_SHRINK) != 0 {
            return Err(EPERM);
        }
        if new_len > current_len && (seals & vfs::F_SEAL_GROW) != 0 {
            return Err(EPERM);
        }
    }
    Ok(())
}

pub(crate) fn open_proc_self_fd(
    path: &str,
    flags: OpenFlags,
) -> Option<Result<Arc<vfs::File>, isize>> {
    let fd_text = path.strip_prefix("/proc/self/fd/")?;
    if fd_text.is_empty() || fd_text.as_bytes().iter().any(|b| !b.is_ascii_digit()) {
        return Some(Err(ENOENT));
    }
    let fd = match fd_text.parse::<usize>() {
        Ok(fd) => fd,
        Err(_) => return Some(Err(ENOENT)),
    };

    let task = current_task().unwrap();
    let (inode, file_type, seals) = {
        let files_ref = task.process.files();
        let fd_table = files_ref.lock();
        let file = match fd_table.get_file(fd) {
            Ok(file) => file,
            Err(e) => return Some(Err(-(e as isize))),
        };
        (file.inode.clone(), file.file_type(), file.memfd_seals())
    };

    let reopened = match vfs::File::new(inode.clone(), _open_flags_to_vfs_flags(flags)) {
        Ok(file) => file,
        Err(e) => return Some(Err(-(e as isize))),
    };
    let seals = seals?;
    reopened.set_memfd_seals(seals);

    if flags.contains(OpenFlags::O_TRUNC) {
        if file_type == vfs::FileType::Dir {
            return Some(Err(EISDIR));
        }
        if !reopened.flags().is_writable() {
            return Some(Err(EACCES));
        }
        if let Err(errno) = check_memfd_truncate_seals(&reopened, 0) {
            return Some(Err(errno));
        }
        if let Err(e) = inode.resize(0) {
            return Some(Err(-(e as isize)));
        }
    }

    Some(Ok(reopened))
}

#[inline]
pub(crate) fn iov_writable_len_for_read(
    user_iov: &UserIoVec,
    offset: usize,
    want: usize,
) -> Result<usize, isize> {
    let accessible = user_iov.accessible_len_at(offset, want, crate::mm::UserAccess::Write);
    if accessible != 0 {
        return Ok(accessible);
    }
    let ubuf = user_iov.writer_buffer_at(offset, 1)?;
    if ubuf.len() == 0 {
        return Err(EFAULT);
    }
    let accessible = user_iov.accessible_len_at(offset, want, crate::mm::UserAccess::Write);
    Ok(accessible.max(1).min(want))
}

pub(crate) fn read_into_user(file: &vfs::File, token: usize, buf: usize, count: usize) -> isize {
    if count == 0 {
        return match file.read(&mut []) {
            Ok(n) => n as isize,
            Err(e) => -(e as isize),
        };
    }

    if file.inode.supports_user_buffer_io() {
        let chunk_cap = count.min(crate::hal::IO_CHUNK_SIZE);
        let mut total = 0usize;
        while total < count {
            let want = (count - total).min(chunk_cap);

            let user_addr = match buf.checked_add(total) {
                Some(v) => v,
                None => {
                    return if total > 0 {
                        total as isize
                    } else {
                        -(SyscallErr::EFAULT as isize)
                    }
                }
            };
            let t0 = crate::task::perf::perf_memory_io_time_now();
            let (writer, accessible) =
                match UserBufferWriter::new_writable_prefix(token, user_addr as *mut u8, want) {
                    Ok(prefix) => prefix,
                    Err(errno) => return if total > 0 { total as isize } else { errno },
                };
            let mut ubuf = writer.into_user_buffer();
            let t1 = crate::task::perf::perf_memory_io_time_now();

            let n = match file.read_user(&mut ubuf) {
                Ok(n) => n,
                Err(e) => {
                    return if total > 0 {
                        total as isize
                    } else {
                        -(e as isize)
                    }
                }
            };
            let t2 = crate::task::perf::perf_memory_io_time_now();
            crate::task::perf::record_pread_uaccess(t1.wrapping_sub(t0));
            crate::task::perf::record_pread_file(t2.wrapping_sub(t1));
            crate::task::perf::record_pread_total_count();
            if n == 0 {
                break;
            }
            total += n;
            if n < accessible {
                break;
            }
            if let Some(task) = current_task() {
                if crate::task::has_actionable_signal(&task) {
                    break;
                }
            }
        }
        return total as isize;
    }

    // kbuf path for pipe/socket/devfs/procfs — avoids ENOSYS probe overhead
    let chunk_cap = count.min(crate::hal::IO_CHUNK_SIZE);
    let mut kbuf = alloc::vec::Vec::new();
    if kbuf.try_reserve(chunk_cap).is_err() {
        return -(SyscallErr::ENOMEM as isize);
    }
    unsafe {
        kbuf.set_len(chunk_cap);
    }

    let mut total = 0usize;
    while total < count {
        let want = (count - total).min(chunk_cap);
        let user_addr = match buf.checked_add(total) {
            Some(v) => v,
            None => {
                return if total > 0 {
                    total as isize
                } else {
                    -(SyscallErr::EFAULT as isize)
                }
            }
        };
        let (mut writer, accessible) =
            match UserBufferWriter::new_writable_prefix(token, user_addr as *mut u8, want) {
                Ok(prefix) => prefix,
                Err(errno) => return if total > 0 { total as isize } else { errno },
            };

        let n = match file.read(&mut kbuf[..accessible]) {
            Ok(n) => n,
            Err(e) => {
                let ret = -(e as isize);
                return if total > 0 { total as isize } else { ret };
            }
        };
        if n == 0 {
            break;
        }

        let copied = match writer.write_from(&kbuf[..n]) {
            Ok(copied) => copied,
            Err(errno) => return if total > 0 { total as isize } else { errno },
        };

        total += copied;
        if copied < n {
            break;
        }
        if let Some(task) = current_task() {
            if crate::task::has_actionable_signal(&task) {
                break;
            }
        }
    }
    total as isize
}

pub(crate) fn read_zero_into_user(token: usize, buf: usize, count: usize) -> isize {
    if count == 0 {
        return 0;
    }

    let chunk_cap = count.min(crate::hal::IO_CHUNK_SIZE);
    let mut total = 0usize;
    while total < count {
        let want = (count - total).min(chunk_cap);
        let user_addr = match buf.checked_add(total) {
            Some(v) => v,
            None => return if total > 0 { total as isize } else { EFAULT },
        };
        let (writer, accessible) =
            match UserBufferWriter::new_writable_prefix(token, user_addr as *mut u8, want) {
                Ok(prefix) => prefix,
                Err(errno) => return if total > 0 { total as isize } else { errno },
            };
        let mut user_buf = writer.into_user_buffer();
        user_buf.clear();
        total += accessible;

        if let Some(task) = current_task() {
            if crate::task::has_actionable_signal(&task) {
                break;
            }
        }
    }
    total as isize
}

