pub(crate) fn write_from_user(file: &vfs::File, token: usize, buf: usize, count: usize) -> isize {
    if count == 0 {
        return match file.write(&[]) {
            Ok(n) => n as isize,
            Err(e) => -(e as isize),
        };
    }

    // Fast path for /dev/null, /dev/zero — skip UserBuffer construction
    if file.inode.is_discard_write() {
        return match file.write_discard(count) {
            Ok(n) => n as isize,
            Err(e) => -(e as isize),
        };
    }

    if file.inode.supports_user_buffer_io() {
        let chunk_cap = count.min(crate::hal::IO_CHUNK_SIZE);
        let mut total = 0usize;
        while total < count {
            let want = (count - total).min(chunk_cap);
            let user_addr = match buf.checked_add(total) {
                Some(v) => v,
                None => {
                    return if total > 0 {
                        total as isize
                    } else {
                        -(SyscallErr::EFAULT as isize)
                    }
                }
            };

            // Foreground split bucket (b): uaccess/PTE translation of the user
            // buffer (accessible_len + UserBufferReader construction). Bucket
            // (c+d+e) is the following file.write_user call. perf_diag only.
            let t0 = crate::task::perf::perf_memory_io_time_now();
            let mut accessible = crate::mm::user_accessible_len(
                token,
                user_addr as *const u8,
                want,
                crate::mm::UserAccess::Read,
            );
            if accessible == 0 {
                if total > 0 {
                    return total as isize;
                }
                accessible = want.min(crate::config::PAGE_SIZE);
            }

            let ubuf = match UserBufferReader::new(token, user_addr as *const u8, accessible) {
                Ok(r) => r.into_user_buffer(),
                Err(errno) => return if total > 0 { total as isize } else { errno },
            };
            let t1 = crate::task::perf::perf_memory_io_time_now();

            let n = match file.write_user(&ubuf) {
                Ok(n) => n,
                Err(e) => {
                    return if total > 0 {
                        total as isize
                    } else {
                        -(e as isize)
                    }
                }
            };
            let t2 = crate::task::perf::perf_memory_io_time_now();
            crate::task::perf::record_write_uaccess(t1.wrapping_sub(t0));
            crate::task::perf::record_write_file(t2.wrapping_sub(t1));
            crate::task::perf::record_write_total_count();
            total += n;
            if n == 0 || n < accessible {
                break;
            }
            if let Some(task) = current_task() {
                if crate::task::has_actionable_signal(&task) {
                    break;
                }
            }
        }
        return total as isize;
    }

    let chunk_cap = count.min(crate::hal::IO_CHUNK_SIZE);
    let mut kbuf = alloc::vec::Vec::new();
    if kbuf.try_reserve(chunk_cap).is_err() {
        return -(SyscallErr::ENOMEM as isize);
    }
    unsafe {
        kbuf.set_len(chunk_cap);
    }

    let mut total = 0usize;
    while total < count {
        let want = (count - total).min(chunk_cap);
        let user_addr = match buf.checked_add(total) {
            Some(v) => v,
            None => {
                return if total > 0 {
                    total as isize
                } else {
                    -(SyscallErr::EFAULT as isize)
                }
            }
        };

        let mut accessible = crate::mm::user_accessible_len(
            token,
            user_addr as *const u8,
            want,
            crate::mm::UserAccess::Read,
        );
        if accessible == 0 {
            if total > 0 {
                return total as isize;
            }
            accessible = want.min(crate::config::PAGE_SIZE);
        }

        let reader = match UserBufferReader::new(token, user_addr as *const u8, accessible) {
            Ok(r) => r,
            Err(errno) => return if total > 0 { total as isize } else { errno },
        };
        let copied = match reader.read_into(&mut kbuf[..accessible]) {
            Ok(n) => n,
            Err(errno) => return if total > 0 { total as isize } else { errno },
        };

        let n = match file.write(&kbuf[..copied]) {
            Ok(n) => n,
            Err(e) => {
                let ret = -(e as isize);
                return if total > 0 { total as isize } else { ret };
            }
        };
        total += n;
        if n == 0 || n < copied {
            break;
        }
        if let Some(task) = current_task() {
            if crate::task::has_actionable_signal(&task) {
                break;
            }
        }
    }
    total as isize
}

