// ── xattr (Extended Attributes) ───────────────────────────────────────

pub(crate) const XATTR_USER_PREFIX: &str = "user.";

pub(crate) fn validate_xattr_name(name: &str) -> Result<&str, isize> {
    if !name.starts_with("user.") {
        return Err(ENOTSUP);
    }
    if name.len() <= XATTR_USER_PREFIX.len() {
        return Err(EINVAL);
    }
    if name.len() > 255 {
        return Err(ERANGE);
    }
    Ok(name)
}

pub(crate) fn validate_xattr_flags(flags: u32) -> Result<(), isize> {
    const XATTR_CREATE: u32 = 1;
    const XATTR_REPLACE: u32 = 2;
    match flags {
        0 | XATTR_CREATE | XATTR_REPLACE => Ok(()),
        _ => Err(EINVAL),
    }
}

pub(crate) fn resolve_path_inode(
    path: &str,
    follow_final: bool,
) -> Result<Arc<dyn vfs::IndexNode>, isize> {
    if let Err(errno) = validate_path_len(path) {
        return Err(errno);
    }
    let start = match resolve_start_inode(AT_FDCWD) {
        Ok(inode) => inode,
        Err(errno) => return Err(errno),
    };
    let (uid, fsgid, groups) = caller_ids_and_groups();
    let perm_err = check_parent_search_access(&start, path, uid, fsgid, &groups);
    if perm_err != SUCCESS {
        return Err(perm_err);
    }
    let inode = crate::fs::vfs_lookup(&start, path, follow_final)?;

    // xattrs are only valid on regular files and directories
    if let Ok(md) = inode.metadata() {
        if md.file_type != FileType::File && md.file_type != FileType::Dir {
            return Err(EOPNOTSUPP);
        }
    }

    Ok(inode)
}

pub(crate) fn fd_to_inode(fd: usize) -> Result<Arc<dyn vfs::IndexNode>, isize> {
    let task = current_task().unwrap();
    let files_ref = task.process.files();
    let fd_table = files_ref.lock();
    let file = fd_table.get_file(fd).map_err(|e| -(e as isize))?;

    // O_PATH fd: xattr operations fail with EBADF (check BEFORE xattr capability)
    if is_path_fd(&file) {
        return Err(EBADF);
    }

    let inode = file.inode.clone();
    drop(fd_table);

    // xattrs are only valid on regular files and directories;
    // Linux fgetxattr on pipes/sockets returns EBADF
    if file.file_type() != FileType::File && file.file_type() != FileType::Dir {
        return Err(EBADF);
    }

    Ok(inode)
}
